// NoSleep.js - Keeps mobile screens awake during active classroom file transfers
(function(window) {
    function NoSleep() {
        this.enabled = false;
        var noSleepVideo = document.createElement("video");
        noSleepVideo.setAttribute("title", "NoSleep");
        noSleepVideo.setAttribute("playsinline", "");
        noSleepVideo.setAttribute("loop", "");
        noSleepVideo.muted = true;
        
        // Lightweight inline silent video data
        var source = document.createElement("source");
        source.src = "data:video/webm;base64,GkXfo0AgQoaBAUL3gQFC8oEEQvOBCEKCQAR3ZWJtQoeBAkKFgQIYUkoAkEpAhIQEB3ZlaWdodIDmAAABWFlleGlmTU0AKgAAAAgAAgESAAQAAAABAAABAAEBAAMAAAABAAABAAAAAAA=";
        source.type = "video/webm";
        noSleepVideo.appendChild(source);

        this.enable = function() {
            if (!this.enabled) {
                this.enabled = true;
                var promise = noSleepVideo.play();
                if (promise !== undefined) {
                    promise.catch(function(e) {
                        // User gesture needed on certain browsers
                        console.log("NoSleep notice:", e);
                    });
                }
            }
        };

        this.disable = function() {
            if (this.enabled) {
                this.enabled = false;
                noSleepVideo.pause();
            }
        };
    }
    window.NoSleep = NoSleep;
})(window);
